1	/*
2	 * KickPi K7 (RK3576) AMP firmware FIT source — openvela on cpu3.
3	 *
4	 * amp3 = openvela nuttx.bin, loaded at 0x41800000 and started by U-Boot
5	 * (CONFIG_ROCKCHIP_AMP) via PSCI CPU_ON before Linux boots.
6	 *
7	 * Reproduction: build openvela (nuttx/nuttx.bin), copy it to the SDK's
8	 * output/rtt3.bin, then pack:
9	 *   cd output && ln -sf ../device/rockchip/.chips/rk3576/amp-k7.its amp.its
10	 *   sed -i '/share {/,/}/d;/compile {/,/}/d' amp.its
11	 *   ../rkbin/tools/mkimage -f amp.its -E -p 0xe00 amp.img
12	 *
13	 * The linux{} node moves kernel_addr_r to 0x42000000 so the decompressed
14	 * kernel cannot overwrite the 0x41800000+8MB AMP region.
15	 */
16	
17	/dts-v1/;
18	/ {
19		description = "KickPi K7 AMP: openvela on cpu3";
20		#address-cells = <1>;
21	
22		images {
23			amp3 {
24				description = "openvela";
25				data = /incbin/("rtt3.bin");
26				type = "firmware";
27				compression = "none";
28				arch = "arm64";
29				cpu = <0x3>;		/* MPIDR: A53 cluster0 core3 */
30				thumb = <0>;
31				hyp = <1>;		/* arm64+hyp = default PE state: pure PSCI CPU_ON */
32				load = <0x41800000>;
33				size = <0x800000>;
34				udelay = <10000>;
35				hash {
36					algo = "sha256";
37				};
38			};
39		};
40	
41		/* build-time only, stripped before mkimage */
42		share {
43			shm_base = <0x47c00000>;
44			shm_size = <0x00400000>;
45			rpmsg_base = <0x47800000>;
46			rpmsg_size = <0x00400000>;
47			primary = <0x0>;
48		};
49	
50		configurations {
51			default = "conf";
52			conf {
53				description = "Rockchip AMP images";
54				rollback-index = <0x0>;
55				loadables = "amp3";
56				signature {
57					algo = "sha256,rsa2048";
58					padding = "pss";
59					key-name-hint = "dev";
60					sign-images = "loadables";
61				};
62				linux {
63					description = "linux-os";
64					arch = "arm64";
65					cpu = <0x0>;
66					thumb = <0>;
67					hyp = <0>;
68					udelay = <0>;
69					load = <0x42000000>;
70					load_c = <0x45480000>;
71				};
72			};
73		};
74	};
