109		/*
110		 * Linux <-> cpu3 RPMsg over shared memory, kicked by reserved GIC
111		 * SPIs (no mailbox needed). interrupts[0] = tx (Linux -> cpu3,
112		 * retriggered, owned by cpu3 via amp-irqs 172); interrupts[1] = rx
113		 * (cpu3 -> Linux, cpu3 sets it pending via GICD_ISPENDR).
114		 * RT-Thread side: rtos/bsp/rockchip/rk3576-k7-amp (rpmsg-lite remote,
115		 * announces "rpmsg-tty" -> /dev/ttyRPMSG0).
116		 */
117		rpmsg: rpmsg@47800000 {
118			compatible = "rockchip,rpmsg-softirq";
119			interrupts = <GIC_SPI 140 IRQ_TYPE_LEVEL_HIGH>,
120				     <GIC_SPI 141 IRQ_TYPE_LEVEL_HIGH>;
121			rockchip,vdev-nums = <1>;
122			rockchip,link-id = <0x03>;	/* master cpu0 / remote cpu3 */
123			reg = <0x0 0x47800000 0x0 0x20000>;
124			memory-region = <&rpmsg_dma_reserved>;
